effect.shader:
// Os valores de Vibrance que têm tabela, em ordem; o 0 (índice 12) é a própria cor e não ocupa linha.
const int N_VALORES = 23;
const int INDICE_DO_ZERO = 12;
const float VALORES[23] = float[23](-100.0, -90.0, -80.0, -70.0, -60.0, -50.0, -40.0, -30.0, -20.0, -10.0, -5.0, -2.0, 0.0,
                                    10.0, 20.0, 30.0, 40.0, 50.0, 60.0, 70.0, 80.0, 90.0, 100.0);

// A LUT 33³ do atlas: 33 ladrilhos 33×33 lado a lado (x = b·33 + r, y = linha0 + g).
vec3 lut(vec3 c, float linha0) {
    vec2 tam = vec2(textureSize(atlas, 0));
    vec3 p = clamp(c, 0.0, 1.0) * 32.0;
    float b0 = floor(p.b);
    float b1 = min(b0 + 1.0, 32.0);
    float t = p.b - b0;
    float v = (linha0 + p.g + 0.5) / tam.y;
    vec3 a = texture(atlas, vec2((b0 * 33.0 + p.r + 0.5) / tam.x, v)).rgb;
    vec3 d = texture(atlas, vec2((b1 * 33.0 + p.r + 0.5) / tam.x, v)).rgb;
    return mix(a, d, t);
}

/** A resposta medida no valor de índice `i` da lista. */
vec3 medido(vec3 c, int i) {
    if (i == INDICE_DO_ZERO) return c;
    return lut(c, 33.0 * float(i < INDICE_DO_ZERO ? i : i - 1));
}

vec3 paraLuz(vec3 c) { return mix(pow((c + 0.055) / 1.055, vec3(2.4)), c / 12.92, vec3(lessThanEqual(c, vec3(0.04045)))); }
vec3 paraTela(vec3 l) { return mix(1.055 * pow(max(l, vec3(0.0)), vec3(1.0 / 2.4)) - 0.055, l * 12.92, vec3(lessThanEqual(l, vec3(0.0031308)))); }

void main() {
    ivec2 T = textureSize(inputImg, 0);
    vec4 fonte = texelFetch(inputImg, ivec2(min(floor(acScreenNorm * vec2(T)), vec2(T) - 1.0)), 0);
    vec3 c = fonte.rgb;

    // Vibrance: mistura linear entre as duas tabelas vizinhas do valor.
    float v = clamp(vibrance, -100.0, 100.0);
    if (v != 0.0) {
        int i = 0;
        for (int k = 0; k < N_VALORES - 1; k++) { if (v >= VALORES[k]) i = k; }
        i = min(i, N_VALORES - 2);
        float t = (v - VALORES[i]) / (VALORES[i + 1] - VALORES[i]);
        c = mix(medido(c, i), medido(c, i + 1), t);
    }

    // Saturation (medido, exato): em luz linear, em volta da luminância com os pesos do ProPhoto.
    if (saturation != 0.0) {
        vec3 l = paraLuz(c);
        float y = dot(l, vec3(0.2880, 0.7119, 0.0001));
        c = clamp(paraTela(clamp(y + (l - y) * (1.0 + clamp(saturation, -100.0, 100.0) / 100.0), 0.0, 1.0)), 0.0, 1.0);
    }

    fragColor = vec4(c, fonte.a);
}
